package com.tencent.weknora.knowledge;

import static org.junit.jupiter.api.Assertions.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import com.sun.net.httpserver.HttpServer;
import com.tencent.weknora.task.*;
import java.net.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.CancellationException;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.config.AutowireCapableBeanFactory;

/** Shared-owner upload, production beans, real HTTP provider and physical generated-question indexes. */
@org.springframework.boot.test.context.SpringBootTest(properties={"weknora.jwt-secret=isolated-native-pipeline-trace-secret","weknora.bridge.enabled=false","weknora.knowledge.processing.enabled=true","weknora.knowledge.upload.enabled=true","weknora.tasks.enabled=true","weknora.tasks.poll-millis=3600000","weknora.retrieve-driver=sqlite","SSRF_WHITELIST=127.0.0.1","SSRF_DNS_WHITELIST_ONLY=true","logging.level.root=WARN","debug=false"})
@org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc
class QuestionGenerationPipelineHttpIntegrationTest {
  @org.springframework.test.context.DynamicPropertySource static void properties(org.springframework.test.context.DynamicPropertyRegistry p){KnowledgeProcessingSpanPipelineHttpIntegrationTest.properties(p);}
  @Autowired AutowireCapableBeanFactory beans;@Autowired QuestionGenerationHandler question;@Autowired QuestionGenerationRepository repository;
  final KnowledgeProcessingSpanPipelineHttpIntegrationTest f=new KnowledgeProcessingSpanPipelineHttpIntegrationTest();
  HttpServer server;final ObjectMapper json=new ObjectMapper();final AtomicInteger questionChats=new AtomicInteger(),summaryChats=new AtomicInteger();Runnable during=()->{};boolean embeddingFailure;
  @BeforeEach void setup()throws Exception {
    beans.autowireBean(f);f.setup();
    server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/v1/",exchange->{try{JsonNode body=json.readTree(exchange.getRequestBody());ObjectNode response;int status=200;if(exchange.getRequestURI().getPath().endsWith("chat/completions")){boolean summary=body.path("messages").get(0).path("role").asText().equals("system");if(summary)summaryChats.incrementAndGet();else questionChats.incrementAndGet();during.run();response=json.createObjectNode().set("choices",json.createArrayNode().add(json.createObjectNode().put("finish_reason","stop").set("message",json.createObjectNode().put("role","assistant").put("content",summary?"{\"summary\":\"Native objective summary.\",\"gist\":\"Native headline\",\"topics\":[\"Access\"]}":"How do access controls work?\nWhich release policy applies?\nWhere are delivery checkpoints?"))));}else if(embeddingFailure){status=400;response=json.createObjectNode().set("error",json.createObjectNode().put("message","PRIVATE_EMBEDDING_DETAIL"));}else {var data=json.createArrayNode();for(int i=0;i<body.path("input").size();i++)data.add(json.createObjectNode().put("index",i).set("embedding",json.createArrayNode().add(1).add(0).add(0)));response=json.createObjectNode().set("data",data);}byte[] bytes=json.writeValueAsBytes(response);exchange.getResponseHeaders().set("Content-Type","application/json");exchange.sendResponseHeaders(status,bytes.length);try(var out=exchange.getResponseBody()){out.write(bytes);}}finally{exchange.close();}});server.start();
    var p=json.createObjectNode().put("provider","generic").put("base_url","http://127.0.0.1:"+server.getAddress().getPort()+"/v1");p.set("embedding_parameters",json.createObjectNode().put("dimension",3));f.jdbc.update("UPDATE models SET parameters=? WHERE id='trace-embedding'",p.toString());f.jdbc.update("INSERT INTO models(id,tenant_id,name,type,source,parameters,is_builtin,status) VALUES('trace-summary',8,'unknown','KnowledgeQA','remote',?,false,'active') ON CONFLICT(id) DO UPDATE SET parameters=excluded.parameters",p.toString());f.jdbc.update("UPDATE knowledge_bases SET summary_model_id='trace-summary',question_generation_config=? WHERE id='trace-kb'","{\"enabled\":true,\"question_count\":3}".getBytes(java.nio.charset.StandardCharsets.UTF_8));
  }
  @AfterEach void stop(){if(server!=null)server.stop(0);f.jdbc.update("UPDATE knowledge_bases SET question_generation_config='{}',summary_model_id='' WHERE id='trace-kb'");}
  String upload(String content,boolean summary)throws Exception {String id=f.upload(content);f.jdbc.update("UPDATE knowledges SET metadata=? WHERE id=?",json.createObjectNode().set("process_overrides",json.createObjectNode().put("summary_enabled",summary)).toString(),id);return id;}
  TaskRecord document(String id)throws Exception {var doc=f.claim("default");assertTrue(f.document.execute(doc,f.cancellation(doc)).path("indexed").asBoolean());f.tasks.complete(doc,json.createObjectNode());return f.claim("postprocess");}
  JsonNode dispatch(TaskRecord post)throws Exception {JsonNode out=f.postprocess.execute(post,f.cancellation(post));f.tasks.complete(post,json.createObjectNode());return out;}
  long pending(String id){return f.jdbc.queryForObject("SELECT pending_subtasks_count FROM knowledges WHERE id=?",Long.class,id);}
  String state(String id){return f.jdbc.queryForObject("SELECT parse_status FROM knowledges WHERE id=?",String.class,id);}
  List<String> textIds(String id){return f.jdbc.queryForList("SELECT id FROM chunks WHERE knowledge_id=? AND chunk_type='text' ORDER BY start_at,id",String.class,id);}
  @Test void freshSharedUploadQuestionsProduceOwnerMetadataVectorsAndPublicDetails()throws Exception {
    String id=upload("Native onboarding access policy.\n\nNative release delivery checkpoints.",false);JsonNode fanout=dispatch(document(id));assertTrue(fanout.path("enqueued_question").asBoolean());assertFalse(fanout.path("enqueued_summary").asBoolean());assertEquals(1,pending(id));var job=f.claim("question");assertEquals(8,job.tenantId());assertEquals(1,job.payload().path("attempt").asLong());assertEquals(4,job.maxAttempts());assertEquals(1800000,job.timeoutMillis());assertEquals("completed",question.execute(job,f.cancellation(job)).path("status").asText());f.tasks.complete(job,json.createObjectNode());assertEquals(0,pending(id));assertEquals("completed",state(id));assertEquals(textIds(id).size(),questionChats.get());assertEquals(textIds(id).size()*4,f.count("lite_embeddings",id));
    for(String chunk:textIds(id)){JsonNode details=f.get(id,"chunks/"+chunk+"/details",f.callerToken,200);JsonNode metadata=details.path("chunk").path("metadata");assertEquals(3,metadata.path("generated_questions").size());JsonNode indexes=details.path("indexes");JsonNode questions=null;for(var row:indexes)if(row.path("kind").asText().equals("questions"))questions=row;assertNotNull(questions);assertTrue(questions.path("available").asBoolean());assertEquals(3,questions.path("questions").size());for(var q:questions.path("questions")){assertTrue(q.path("current").asBoolean());assertTrue(q.path("vector_indexed").asBoolean());assertTrue(q.path("keyword_indexed").asBoolean());}f.get(id,"chunks/"+chunk+"/details",f.foreignToken,403);}
    JsonNode index=f.get(id,"index-status",f.callerToken,200);for(var row:index.path("indexes"))if(row.path("kind").asText().equals("questions")){assertEquals("completed",row.path("status").asText(),index.toString()+" SQL="+f.jdbc.queryForList("SELECT id,content_revision,metadata FROM chunks WHERE knowledge_id=?",id));assertEquals(textIds(id).size()*3,row.path("count").asInt());}
    f.assertNativeTrace(id,"done");for(String alias:List.of("spans","stages")){var trace=f.get(id,alias,f.callerToken,200).path("trace");var group=f.node(trace,"postprocess.question");var batch=f.node(trace,"postprocess.question.batch[0]");assertEquals(group.path("span_id").asText(),batch.path("parent_span_id").asText());assertEquals("done",batch.path("status").asText());assertEquals(textIds(id).size()*3,batch.path("output").path("questions_generated").asInt());}
    // Vector payloads are present in vec0, not only relational index rows.
    assertEquals(f.count("lite_embeddings",id),f.jdbc.execute((org.springframework.jdbc.core.ConnectionCallback<Long>)c->{new com.tencent.weknora.retrieval.SQLiteVectorExtension(java.nio.file.Path.of(System.getProperty("weknora.sqlite.vec.extension"))).load(c);try(var s=c.prepareStatement("SELECT COUNT(*) FROM vec_embeddings_3 v JOIN lite_embeddings e ON e.id=v.rowid WHERE e.knowledge_id=?")){s.setString(1,id);try(var r=s.executeQuery()){return r.getLong(1);}}}));
  }
  @Test void summaryAndQuestionsShareCounterAndCompleteOnlyAfterBothTerminalWorkers()throws Exception {
    String id=upload("Documented policy has sufficient text for summary and generated questions.",true);JsonNode plan=dispatch(document(id));assertTrue(plan.path("enqueued_summary").asBoolean());assertEquals(1,plan.path("enqueued_question_count").asInt());assertEquals(2,pending(id));var q=f.claim("question");question.execute(q,f.cancellation(q));f.tasks.complete(q,json.createObjectNode());assertEquals(1,pending(id));assertEquals("finalizing",state(id));var summary=f.claim("summary");f.summary.execute(summary,f.cancellation(summary));f.tasks.complete(summary,json.createObjectNode());assertEquals(0,pending(id));assertEquals("completed",state(id));assertEquals(1,summaryChats.get());assertEquals("Native objective summary.",f.jdbc.queryForObject("SELECT description FROM knowledges WHERE id=?",String.class,id));assertEquals(1,f.jdbc.queryForObject("SELECT COUNT(*) FROM chunks WHERE knowledge_id=? AND chunk_type='summary'",Integer.class,id));repository.drain(q);assertEquals(0,pending(id));f.assertNativeTrace(id,"done");
  }
  @Test void orderedWindowsOfTwentyPreserveAdjacentBoundaryIdsAndAttempt()throws Exception {
    var content=new StringBuilder();for(int i=0;i<42;i++)content.append("Access policy section "+i+" describes release safeguards and delivery rules.\n\n");String id=upload(content.toString(),true);var doc=document(id);List<String> ids=textIds(id);assertTrue(ids.size()>20);var plan=dispatch(doc);int expected=(ids.size()+19)/20;assertEquals(expected,plan.path("enqueued_question_count").asInt());assertEquals(expected+1,pending(id));var jobs=f.jdbc.queryForList("SELECT payload,queue,max_attempts,timeout_millis FROM java_task_jobs WHERE type='question:generation' AND json_extract(payload,'$.knowledge_id')=? ORDER BY json_extract(payload,'$.batch_index')",id);assertEquals(expected,jobs.size());for(int n=0;n<jobs.size();n++){var row=jobs.get(n);JsonNode p=json.readTree(row.get("payload").toString());int start=n*20,end=Math.min(start+20,ids.size());assertEquals(json.valueToTree(ids.subList(start,end)),p.path("chunk_ids"));assertEquals(start>0?ids.get(start-1):"",p.path("prev_chunk_id").asText());assertEquals(end<ids.size()?ids.get(end):"",p.path("next_chunk_id").asText());assertEquals(1,p.path("attempt").asLong());assertEquals("question",row.get("queue"));assertEquals(4,((Number)row.get("max_attempts")).intValue());assertEquals(1800000,((Number)row.get("timeout_millis")).longValue());}
  }
  @Test void partialQueueFailureRollsBackCounterSummaryJobAndQuestionGroup()throws Exception {
    String id=upload("Atomic summary and question queue handoff preserves source state on failure.",true);var post=document(id);var snapshot=f.processing.load(post).orElseThrow();JsonNode effective=new KnowledgeProcessConfig(json).resolve(snapshot.knowledgeBase(),snapshot.knowledge().path("metadata").get("process_overrides"));var count=new AtomicInteger();KnowledgeFileUpload.Enqueuer producer=(owner,type,p,options)->{if(count.incrementAndGet()==2)throw new java.io.IOException("synthetic second enqueue failure");return f.tasks.enqueue(owner,type,UUID.randomUUID().toString(),p,options.maxRetries()+1,Duration.ZERO,options.queue(),options.timeout()).id();};var manager=beans.getBean(org.springframework.transaction.PlatformTransactionManager.class);var fanout=new QuestionGenerationFanout(f.jdbc,json,repository,producer,manager,Clock.systemUTC(),f.tracker);assertThrows(IllegalStateException.class,()->fanout.handoff(post,snapshot,effective));assertEquals("processing",state(id));assertEquals(0,pending(id));assertEquals(0,f.jdbc.queryForObject("SELECT COUNT(*) FROM java_task_jobs WHERE type IN ('summary:generation','question:generation') AND json_extract(payload,'$.knowledge_id')=?",Integer.class,id));assertEquals(0,f.jdbc.queryForObject("SELECT COUNT(*) FROM knowledge_processing_spans WHERE knowledge_id=? AND name='postprocess.question'",Integer.class,id));
  }
  @Test void lostLeaseCannotPublishOrDrainEvenWhenKnowledgeAlsoCancels()throws Exception {
    String id=upload("Question generation must fence a replacement lease during provider output.",false);dispatch(document(id));var job=f.claim("question");during=()->{f.jdbc.update("UPDATE java_task_jobs SET lease_owner='successor' WHERE id=?",job.id());f.jdbc.update("UPDATE knowledges SET parse_status='cancelled' WHERE id=?",id);};assertThrows(CancellationException.class,()->question.execute(job,f.cancellation(job)));assertEquals(1,pending(id));assertEquals(0,f.jdbc.queryForObject("SELECT COUNT(*) FROM chunks WHERE knowledge_id=? AND metadata IS NOT NULL",Integer.class,id));assertEquals(textIds(id).size(),f.count("lite_embeddings",id));
  }
  @Test void supersededAttemptNeverCallsModelOrDrainsNewSlots()throws Exception {
    String id=upload("Question generation must leave the successor attempt counter untouched.",false);dispatch(document(id));var job=f.claim("question");f.tracker.open(8,id,"successor");f.jdbc.update("UPDATE knowledges SET pending_subtasks_count=2 WHERE id=?",id);assertEquals("attempt_superseded",question.execute(job,f.cancellation(job)).path("skipped").asText());assertEquals(0,questionChats.get());assertEquals(2,pending(id));assertEquals(0,f.jdbc.queryForObject("SELECT COUNT(*) FROM java_question_task_drains WHERE task_id=?",Integer.class,job.id()));
  }
  @Test void embeddingRetryKeepsMetadataAndOnlyFinalFailureDrainsWithoutPoisoningRoot()throws Exception {
    String id=upload("Question metadata checkpoint survives embedding failures across worker retries.",false);dispatch(document(id));var job=f.claim("question");embeddingFailure=true;assertThrows(RuntimeException.class,()->question.execute(job,f.cancellation(job)));assertEquals(1,pending(id));assertEquals(textIds(id).size(),f.count("lite_embeddings",id));assertTrue(f.jdbc.queryForObject("SELECT COUNT(*) FROM chunks WHERE knowledge_id=? AND metadata IS NOT NULL",Integer.class,id)>0);f.jdbc.update("UPDATE java_task_jobs SET attempts=4 WHERE id=?",job.id());var last=f.tasks.get(8,job.id()).orElseThrow();assertThrows(RuntimeException.class,()->question.execute(last,f.cancellation(last)));assertEquals(0,pending(id));assertEquals("completed",state(id));assertEquals("done",f.get(id,"spans",f.callerToken,200).path("trace").path("status").asText());repository.drain(last);assertEquals(0,pending(id));
  }
  @Test void businessCancellationAcksWithoutPublishingButDrainsItsOwnSlot()throws Exception {
    String id=upload("Question generation must recheck business cancellation after provider output.",false);dispatch(document(id));var job=f.claim("question");during=()->f.jdbc.update("UPDATE knowledges SET parse_status='cancelled' WHERE id=?",id);assertEquals("knowledge_cancelled",question.execute(job,f.cancellation(job)).path("skipped").asText());assertEquals(0,pending(id));assertEquals("cancelled",state(id));assertEquals(1,questionChats.get());assertEquals(0,f.jdbc.queryForObject("SELECT COUNT(*) FROM chunks WHERE knowledge_id=? AND metadata IS NOT NULL",Integer.class,id));assertEquals(textIds(id).size(),f.count("lite_embeddings",id));
  }

  @Test void foreignPayloadOwnerOrBaseCannotPublishOrDrainFinalDelivery()throws Exception {
    String id=upload("Question generation owner and knowledge base are bound before any provider call.",false);dispatch(document(id));var job=f.claim("question");f.jdbc.update("UPDATE java_task_jobs SET attempts=4,payload=? WHERE id=?",((ObjectNode)job.payload().deepCopy()).put("tenant_id",9).toString(),job.id());var ownerMismatch=f.tasks.get(8,job.id()).orElseThrow();assertThrows(TaskFailure.class,()->question.execute(ownerMismatch,f.cancellation(ownerMismatch)));assertEquals(0,questionChats.get());assertEquals(1,pending(id));f.jdbc.update("UPDATE java_task_jobs SET payload=? WHERE id=?",((ObjectNode)job.payload().deepCopy()).put("knowledge_base_id","foreign-kb").toString(),job.id());var baseMismatch=f.tasks.get(8,job.id()).orElseThrow();assertThrows(TaskFailure.class,()->question.execute(baseMismatch,f.cancellation(baseMismatch)));assertEquals(1,pending(id));assertEquals(0,questionChats.get());assertEquals(0,f.jdbc.queryForObject("SELECT COUNT(*) FROM java_question_task_drains WHERE task_id=?",Integer.class,job.id()));assertEquals(textIds(id).size(),f.count("lite_embeddings",id));
  }
}
